/* 台账内图片轮播、文档预览和按权限下载。 */
window.EamFileViewer=(()=>{let files=[],index=0,url=null,request=0;const dialog=document.getElementById('file-viewer');if(!dialog)return null;
function cleanup(){request++;if(url)URL.revokeObjectURL(url);url=null;document.getElementById('viewer-content').replaceChildren();}
async function show(){cleanup();const ticket=request,f=files[index];Eam.text('viewer-title',f.name+' / '+f.revision);Eam.text('viewer-counter',(index+1)+' / '+files.length);Eam.text('viewer-error','');document.getElementById('viewer-download').disabled=!EamProduct.filePermission(Eam.s.role,'download',f);document.getElementById('viewer-prev').disabled=files.length<2;document.getElementById('viewer-next').disabled=files.length<2;
try{if(!EamProduct.filePermission(Eam.s.role,'view',f))throw Error('此文件关联已移除，无查看权限');const blob=await EamFiles.get(f);if(ticket!==request)return;url=URL.createObjectURL(blob);const box=document.getElementById('viewer-content');if(f.category==='image'){const img=document.createElement('img');img.src=url;img.alt=f.name;box.append(img);}else if(/\.pdf$/i.test(f.name)){const frame=document.createElement('iframe');frame.src=url;frame.title=f.name;frame.setAttribute('sandbox','');box.append(frame);}else if(/\.txt$/i.test(f.name)){const pre=document.createElement('pre');pre.textContent=await blob.text();if(ticket===request)box.append(pre);}else{Eam.text('viewer-error',f.category==='model'?'模型内容已保存；真实GLB/glTF查看器待接入。':'该格式需要文件服务转换为PDF预览；当前可按权限下载原文件。');}}
catch(e){if(ticket===request)Eam.text('viewer-error',e.message);}}
async function download(f){if(!EamProduct.filePermission(Eam.s.role,'download',f)){Eam.message('当前角色没有原文件下载权限');return;}try{const blob=await EamFiles.get(f),link=document.createElement('a'),u=URL.createObjectURL(blob);link.href=u;link.download=f.name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(u),1000);Eam.s.localFileAccess ||= [];Eam.s.localFileAccess.push({fileId:f.id,action:'download_requested',person:Eam.s.person,time:new Date().toISOString()});Eam.save();}catch(e){Eam.message(e.message);}}
document.getElementById('viewer-close').onclick=()=>dialog.close();dialog.addEventListener('close',cleanup);document.getElementById('viewer-prev').onclick=()=>{index=(index+files.length-1)%files.length;show();};document.getElementById('viewer-next').onclick=()=>{index=(index+1)%files.length;show();};document.getElementById('viewer-download').onclick=()=>download(files[index]);dialog.addEventListener('keydown',e=>{if(files.length>1&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();index=(index+files.length+(e.key==='ArrowLeft'?-1:1))%files.length;show();}});
return {open:(items,i=0)=>{files=items;index=i;if(!dialog.open)dialog.showModal();show();},download};})();
